return [{ json: { imageBase64: base64Image } }];

const responses = $input.first().json.responses;
if (!responses || responses.length === 0) return [{ json: { text: '' } }];
const fullText = responses[0]?.fullTextAnnotation?.text || responses[0]?.textAnnotations?.[0]?.description || '';
return [{ json: { text: fullText } }];

const raw = $input.first().json;
const rawText = raw?.choices?.[0]?.message?.content || '';

function stripFences(str) {
  return str.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
}
function randomId(prefix, digits) {
  const num = Math.floor(Math.random() * Math.pow(10, digits));
  return prefix + String(num).padStart(digits, '0');
}
function isEmpty(val) {
  if (val === null || val === undefined) return true;
  const s = String(val).trim().toLowerCase();
  return s === '' || s === 'null' || s === 'undefined';
}
function cat(val, fallback) {
  if (isEmpty(val)) return fallback || 'N/A';
  return String(val).trim();
}
function num(val) {
  if (isEmpty(val)) return '0';
  const str = String(val).replace(/[^0-9.]/g, '');
  return str || '0';
}
function todayDateString() {
  const now = new Date();
  const dd = String(now.getDate()).padStart(2,'0');
  const mm = String(now.getMonth()+1).padStart(2,'0');
  const yyyy = now.getFullYear();
  return `${dd}-${mm}-${yyyy}`;
}
function nowDateTimeString() {
  const now = new Date();
  let h = now.getHours();
  const mm = String(now.getMinutes()).padStart(2,'0');
  const ss = String(now.getSeconds()).padStart(2,'0');
  const ampm = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  return `${now.getMonth()+1}/${now.getDate()}/${now.getFullYear()} ${h}:${mm}:${ss} ${ampm}`;
}

// ── Convert any date format to DD-MM-YYYY ─────────────────────────────────
function toDisplayFormat(val) {
  const s = String(val).trim();
  // YYYY-MM-DD → DD-MM-YYYY
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
    const [y, m, d] = s.split('-');
    return `${d}-${m}-${y}`;
  }
  // M/D/YYYY → DD-MM-YYYY
  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(s)) {
    const [m, d, y] = s.split('/');
    return `${String(d).padStart(2,'0')}-${String(m).padStart(2,'0')}-${y}`;
  }
  // Already DD-MM-YYYY or unknown — return as-is
  return s;
}

function normalizeBrandCode(brandName, productName) {
  const source = !isEmpty(brandName) ? String(brandName) : (!isEmpty(productName) ? String(productName) : '');
  if (!source) return 'N/A';
  const b = source.trim().toUpperCase();
  const map = {
    'DELL':'DELL','HP':'HP','HEWLETT PACKARD':'HP','APPLE':'APPLE',
    'SAMSUNG':'SAMSUNG','LENOVO':'LENOVO','ASUS':'ASUS','ACER':'ACER',
    'MICROSOFT':'MICROSOFT','SONY':'SONY','LG':'LG','TOSHIBA':'TOSHIBA',
    'NITRILE':'NITRILE','LATEX':'LATEX','VINYL':'VINYL','COTTON':'COTTON',
    'NIKE':'NIKE','ADIDAS':'ADIDAS','PUMA':'PUMA'
  };
  for (const [key, code] of Object.entries(map)) {
    if (b.includes(key)) return code;
  }
  const firstWord = b.split(/[\s\-_\/]+/)[0].replace(/[^A-Z0-9]/g, '');
  return firstWord || 'N/A';
}

function normalizeCategoryCode(categoryName, productName) {
  const source = !isEmpty(categoryName) ? String(categoryName) : (!isEmpty(productName) ? String(productName) : '');
  if (!source) return 'GENERAL';
  const c = source.trim().toUpperCase();
  const map = {
    'COMPUTER':'COMPUTERS','DESKTOP':'COMPUTERS','LAPTOP':'LAPTOPS',
    'NOTEBOOK':'LAPTOPS','PHONE':'PHONES','MOBILE':'PHONES','SMARTPHONE':'PHONES',
    'MONITOR':'MONITORS','DISPLAY':'MONITORS','TABLET':'TABLETS',
    'PRINTER':'PRINTERS','ACCESSORY':'ACCESSORIES','ACCESSORIES':'ACCESSORIES',
    'KEYBOARD':'ACCESSORIES','MOUSE':'ACCESSORIES','SERVER':'SERVERS',
    'STORAGE':'STORAGE','NETWORKING':'NETWORKING','SOFTWARE':'SOFTWARE',
    'GLOVE':'SAFETY_EQUIPMENT','SAFETY':'SAFETY_EQUIPMENT','MEDICAL':'MEDICAL_SUPPLIES',
    'CLOTHING':'CLOTHING','APPAREL':'CLOTHING','SHOE':'FOOTWEAR','BOOT':'FOOTWEAR',
    'FURNITURE':'FURNITURE','CHAIR':'FURNITURE','DESK':'FURNITURE',
    'TOOL':'TOOLS','DRILL':'TOOLS','SAW':'TOOLS',
    'FOOD':'FOOD_BEVERAGE','DRINK':'FOOD_BEVERAGE','BEVERAGE':'FOOD_BEVERAGE'
  };
  for (const [key, code] of Object.entries(map)) {
    if (c.includes(key)) return code;
  }
  const cleaned = c.replace(/[^A-Z0-9]/g, '_').replace(/_+/g, '_').replace(/^_|_$/g, '');
  return cleaned.substring(0, 20) || 'GENERAL';
}

function validateCustomerId(val) {
  if (isEmpty(val)) return randomId('CUST', 10);
  const str = String(val).trim();
  if (str.toUpperCase().startsWith('CUST')) return str;
  return randomId('CUST', 10);
}

const cleaned = stripFences(rawText);
let output;
try {
  output = JSON.parse(cleaned);
} catch(e) {
  return [{ json: { _parse_error: cleaned.substring(0, 300) } }];
}

const order_ts    = isEmpty(output.order_ts) ? nowDateTimeString() : String(output.order_ts);
const channel     = cat(output.channel, 'Online');
const customerRaw = output.customer || {};
const customer_id = validateCustomerId(customerRaw.customer_id);
const order_id    = !isEmpty(output.order_id) ? String(output.order_id)
                  : (!isEmpty(output.invoice_id) ? String(output.invoice_id)
                  : 'ORD' + String(Math.floor(Math.random() * 9000000000) + 1000000000));

// ── dt always in DD-MM-YYYY ───────────────────────────────────────────────
const dt = isEmpty(output.dt) ? todayDateString() : toDisplayFormat(output.dt);

let items = [];
try {
  if (typeof output.items === 'string') items = JSON.parse(stripFences(output.items));
  else if (Array.isArray(output.items)) items = output.items;
  else items = [{}];
} catch(e) { items = [{}]; }
if (items.length === 0) items = [{}];

const orderRows      = [];
