  const brandCode    = normalizeBrandCode(item.brand_name, productName);
  const categoryName = !isEmpty(item.category_name) ? String(item.category_name).trim() : productName;
  const categoryCode = normalizeCategoryCode(item.category_name, productName);
  const itemSeq      = isEmpty(item.item_seq) ? '0' : String(item.item_seq);
  const product_id   = !isEmpty(item.product_id) ? String(item.product_id)
                     : (brandCode !== 'N/A' && itemSeq !== '0' ? `${brandCode}-${itemSeq}` : randomId('PROD', 7));

  orderRows.push({
    dt:                  String(dt),
    order_ts:            String(order_ts),
    customer_id:         String(customer_id),
    order_id:            String(order_id),
    channel:             String(channel),
    coupon_code:         cat(output.coupon_code, 'N/A'),
    item_seq:            String(itemSeq),
    product_id:          String(product_id),
    quantity:            String(num(item.quantity)),
    unit_price_currency: cat(item.unit_price_currency, 'USD'),
    unit_price:          String(num(item.unit_price)),
    discount_pct:        isEmpty(item.discount_pct) ? '0%' : String(item.discount_pct),
    tax_amount:          String((() => {
      const price = parseFloat(num(item.unit_price)) || 0;
      const qty   = parseFloat(num(item.quantity))   || 1;
      const rate  = parseFloat(String(item.tax_rate || output.tax_rate || '0').replace(/[^0-9.]/g, '')) || 0;
      return (Math.round(price * qty * rate / 100 * 100) / 100).toFixed(2);
    })())
  });

  if (!seenProducts.has(product_id)) {
    seenProducts.add(product_id);
    productRows.push({
      product_id:    String(product_id),
      sku:           cat(item.sku, 'N/A'),
      product_name:  String(productName),
      category_code: String(categoryCode),
      brand_code:    String(brandCode),
      color:         cat(item.color, 'N/A'),
      size:          cat(item.size, 'N/A'),
      material:      cat(item.material, 'N/A'),
      weight_grams:  String(num(item.weight_grams)),
      length_cm:     String(num(item.length_cm)),
      width_cm:      String(num(item.width_cm)),
      height_cm:     String(num(item.height_cm)),
      rating_count:  String(num(item.rating_count))
    });
  }

  if (!seenCategories.has(categoryCode)) {
    seenCategories.add(categoryCode);
    categoryRows.push({
      category_code: String(categoryCode),
      category_name: String(categoryName)
    });
  }

  if (!seenBrands.has(brandCode)) {
    seenBrands.add(brandCode);
    brandRows.push({
      brand_code:    String(brandCode),
      brand_name:    String(brandName),
      category_code: String(categoryCode)
    });
  }
}

