if (!dateRow && invoiceDate) {
  const d = new Date(invoiceDate);
  const dayNames = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
  const month = d.getMonth() + 1;
  const quarter = Math.ceil(month / 3).toString();
  dateRow = {
    date: invoiceDate,
    year: String(d.getFullYear()),
    day_name: dayNames[d.getDay()],
    quarter: quarter,
    week_of_year: null
  };
}

const rows = dateRow ? [dateRow] : [];
const header = 'date,year,day_name,quarter,week_of_year';
const csvLines = rows.map(r => `${r.date},${r.year},${r.day_name},${r.quarter},${r.week_of_year ?? ''}`);
const csvStr = header + '\n' + csvLines.join('\n');

const buffer = Buffer.from(csvStr, 'utf8');
return [{
  json: { filename: 'dates' },
  binary: { data: { data: buffer.toString('base64'), mimeType: 'text/csv', fileName: 'dates.csv' } }
}];

